// Inside a Scene subclass; invoke this when rebuilding an interactive sequence.
private generation = 0;
async replay() {
  const generation = ++this.generation;
  await this.reset();
  if (generation !== this.generation) return;
  try {
    await this.run();
  } catch (error) {
    if (error instanceof Error && error.message === 'Scene Reset') return;
    throw error;
  }
}
